    use super::*;

    /// `_throw(node)`.
    pub fn throw_<R>(ast: Ast<'_>, node: NodeId) -> R {
        let mut type_name = ast.node(node).runtime_type();
        if let Some(name) = type_name.strip_suffix("Impl") {
            type_name = name;
        }
        panic!("Exception: Missing implementation of visit{type_name}");
    }

